document.addEventListener('DOMContentLoaded',function(){const a=document.getElementById('companies-grid'),b=document.getElementById('company-search');let c=[],d='';const e=CompanyApp.loadFromCache();if(e&&Array.isArray(e.companies)){c=e.companies;renderCompanies(c);CompanyApp.fetchData(f=>{c=f.companies;filterAndRender()},null,!0)}else{CompanyApp.fetchData(f=>{c=f.companies;renderCompanies(c)},g=>showError(g))}let f;b.addEventListener('input',function(){clearTimeout(f);f=setTimeout(()=>{d=b.value.trim().toLowerCase();filterAndRender()},150)});function filterAndRender(){let g=c;if(d){g=c.filter(h=>{const i=(h.arName||h.name||'').toLowerCase(),j=(h.arDescription||h.description||'').toLowerCase();return i.includes(d)||j.includes(d)})}renderCompanies(g)}function renderCompanies(g){a.innerHTML='';if(g.length===0){a.innerHTML='<div class="col-12"><div class="empty-state"><i class="fa-solid fa-building-circle-xmark fa-4x"></i><h4>لم يتم العثور على أي شركة</h4><p class="text-muted">تأكد من كتابة الاسم بشكل صحيح أو جرب كلمة بحث أخرى.</p></div></div>';return}g.forEach(h=>{const i=h.slug?`slug=${encodeURIComponent(h.slug)}`:`id=${encodeURIComponent(h.id)}`,j=`details?${i}`,k=document.createElement('div');k.className='col-md-4 col-sm-6';k.style.marginBottom='30px';k.innerHTML=`<div class="company-card"><div class="company-logo-wrapper"><img src="${h.logo}" alt="شعار شركة ${h.arName||h.name}" class="company-logo" loading="lazy" onerror="this.src='https://connecttag.org/assets/img/connect-tag-official-logo.webp';"></div><h2 class="company-name">${h.arName||h.name}</h2><p class="company-desc">${h.arDescription||h.description||'شركة اتصالات يمنية رائدة تقدم خدمات الجوال والإنترنت والباقات المتنوعة.'}</p><a href="${j}" class="btn-details">عرض الخدمات والباقات <i class="fa-solid fa-arrow-left-long"></i></a></div>`;a.appendChild(k)})}function showError(g){a.innerHTML=`<div class="col-12 text-center py-5 text-danger font-weight-bold"><i class="fa-solid fa-circle-exclamation fa-2x mb-3"></i><p>${g}</p></div>`}});